test='''\nint main(void){g_mem=calloc(1,32u<<20);uint8_t*mb=g_mem;CPU c={0};assert(mb);g_camera_pad_active=1;g_camera_pad_x=30000;g_camera_pad_y=30000;factor=1.f;c.esp=0x2000;W32(c.esp,0x52dbe6);W32(0xfd5ba4,0);nat_camera_input(&c);float y=rt_f32(R32(0x10a18a0));assert(fabsf(y*y-0.5f)<1e-5f);assert(rt_f32(R32(0x10a18a4))==1.f);factor=2.f;c.esp=0x2000;nat_camera_input(&c);y=rt_f32(R32(0x10a18a0));assert(fabsf(y*y-1.f)<1e-5f);W32(0xfd5ba4,1);c.esp=0x2000;nat_camera_input(&c);y=rt_f32(R32(0x10a18a0));assert(fabsf(y*y-1.f)<1e-5f);assert(rt_f32(R32(0x10a18a4))==1.f);g_camera_pad_active=0;c.esp=0x2000;nat_camera_input(&c);assert(rt_f32(R32(0x10a18a0))==-1.f);assert(rt_f32(R32(0x10a18a4))==1.f);puts("first-person sensitivity, quadratic vertical response and mode guards OK");free(g_mem);return 0;}\n'''
